import { ImageTrail } from "solen-design/react";

const items = [
  "/images/trail-1.jpg",
  "/images/trail-2.jpg",
  "/images/trail-3.jpg",
  "/images/trail-4.jpg"
];

<div style={{ position: "relative", width: "100vw", height: "100vh" }}>
  <ImageTrail
    items={items}
    size={190}
    threshold={80}
    rotation={12}
    sizeVariance={0.4}
    drift={0.6}
    zoom={1.2}
    flash={0.25}
  />
</div>
